/**
 * Westcoast Rippers — wave-dividers.js
 * Layered PNG wave animation inspired by pirate-style background-position-x scrolling.
 * Three wave layers scroll at different speeds and directions for parallax depth.
 */
(function () {
  'use strict';

  // Base64-embedded wave PNGs (waves-1 = front/foam, waves-2 = mid, waves-3 = back/deep)
  var W1 = 'data:image/png;base64,';
  var W2 = 'data:image/png;base64,';
  var W3 = 'data:image/png;base64,';

  function injectStyles() {
    if (document.getElementById('kcak-wave-styles')) return;
    var style = document.createElement('style');
    style.id = 'kcak-wave-styles';
    style.textContent = [
      '/* ── Pirate-style wave dividers ── */',
      '.kcak-ocean {',
      '  position: relative;',
      '  width: 100%;',
      '  height: 90px;',
      '  overflow: hidden;',
      '  line-height: 0;',
      '  margin-top: -2px;',
      '  margin-bottom: -2px;',
      '}',
      '.kcak-wave {',
      '  position: absolute;',
      '  left: 0;',
      '  width: 100%;',
      '  height: 100%;',
      '  background-repeat: repeat-x;',
      '  background-size: 1000px 100%;',
      '  will-change: background-position-x;',
      '}',
      '.kcak-wave--back {',
      '  bottom: 0;',
      '  height: 75%;',
      '  animation: kcakWave1 6s linear infinite;',
      '  opacity: 0.55;',
      '}',
      '.kcak-wave--mid {',
      '  bottom: 0;',
      '  height: 60%;',
      '  animation: kcakWave2 4s linear infinite;',
      '  opacity: 0.75;',
      '}',
      '.kcak-wave--front {',
      '  bottom: 0;',
      '  height: 50%;',
      '  animation: kcakWave1 3s linear infinite;',
      '  opacity: 1;',
      '}',
      '@keyframes kcakWave1 {',
      '  0%   { background-position-x: 1000px; }',
      '  100% { background-position-x: 0; }',
      '}',
      '@keyframes kcakWave2 {',
      '  0%   { background-position-x: 0; }',
      '  100% { background-position-x: 1000px; }',
      '}',
      '@media (min-width: 1150px) {',
      '  .kcak-wave { background-size: 100vw 100%; }',
      '  @keyframes kcakWave1 {',
      '    0%   { background-position-x: 100vw; }',
      '    100% { background-position-x: 0; }',
      '  }',
      '  @keyframes kcakWave2 {',
      '    0%   { background-position-x: 0; }',
      '    100% { background-position-x: 100vw; }',
      '  }',
      '}',
    ].join('\n');
    document.head.appendChild(style);
  }

  function initDivider(wrap) {
    var canvas = wrap.querySelector('canvas');
    var bgColor = canvas ? (canvas.dataset.to || '#040D1A') : '#040D1A';
    if (canvas) wrap.removeChild(canvas);

    var ocean = document.createElement('div');
    ocean.className = 'kcak-ocean';
    ocean.style.background = bgColor;

    // Back layer — waves-3 (deep, slowest)
    var back = document.createElement('div');
    back.className = 'kcak-wave kcak-wave--back';
    back.style.backgroundImage = 'url(' + W3 + ')';

    // Mid layer — waves-2 (scrolls opposite)
    var mid = document.createElement('div');
    mid.className = 'kcak-wave kcak-wave--mid';
    mid.style.backgroundImage = 'url(' + W2 + ')';

    // Front layer — waves-1 (foam, fastest)
    var front = document.createElement('div');
    front.className = 'kcak-wave kcak-wave--front';
    front.style.backgroundImage = 'url(' + W1 + ')';

    ocean.appendChild(back);
    ocean.appendChild(mid);
    ocean.appendChild(front);
    wrap.appendChild(ocean);
  }

  function init() {
    injectStyles();
    document.querySelectorAll('.wave-divider-wrap').forEach(initDivider);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

})();
